import React from "react";

const tips = [
  'Selalu cek domain pengirim.',
  'Hover sebelum klik link.',
  'Jangan panik, jangan tergesa.',
  'Verifikasi ke sumber resmi.',
];

export default function Slide8TipsDeteksi({ onNext, onPrev }) {
  return (
    <div className="slide-content bg-gradient-to-r from-[#e6f4ea] to-[#b7e0c7] rounded-2xl p-8 md:p-12 shadow-xl">
      <h2 className="slide-title mb-6 text-green-700">Tips Mendeteksi Phishing</h2>
      <ul className="text-lg text-gray-800 mb-8 space-y-3">
        {tips.map((tip, i) => (
          <li key={i} className="flex items-center gap-3"><span className="text-green-600">✔</span>{tip}</li>
        ))}
      </ul>
      <div className="flex gap-4 justify-center">
        <button onClick={onPrev} className="bg-gray-200 text-green-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-300 transition">Back</button>
        <button onClick={onNext} className="bg-green-600 text-white px-6 py-2 rounded-lg font-bold text-lg shadow hover:bg-green-700 transition">Next</button>
      </div>
    </div>
  );
}
